-- OpenNewsletter — database tables (prefix on_). Generated by tools/build-sql.php: edit lib/schema.php instead.
-- Import it in phpMyAdmin, then copy credentials-sample.php to credentials.php and fill it in (secret_key included).

CREATE TABLE IF NOT EXISTS `on_meta` (
    `k` VARCHAR(40) NOT NULL PRIMARY KEY,
    `v` VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `on_users` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(80) NOT NULL,
    `email` VARCHAR(190) NOT NULL,
    `email_verified_at` DATETIME NULL,
    `password_hash` VARCHAR(255) NOT NULL DEFAULT '',
    `google_sub` VARCHAR(64) NULL,
    `ui_lang` VARCHAR(5) NOT NULL DEFAULT 'en',
    `fav_templates` VARCHAR(1000) NOT NULL DEFAULT '[]',
    `status` ENUM('active','disabled') NOT NULL DEFAULT 'active',
    `created_at` DATETIME NOT NULL,
    `last_login_at` DATETIME NULL,
    UNIQUE KEY `uq_email` (`email`),
    UNIQUE KEY `uq_google` (`google_sub`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `on_auth_tokens` (
    `token_hash` CHAR(64) NOT NULL PRIMARY KEY,
    `user_id` INT UNSIGNED NOT NULL,
    `csrf_token` CHAR(48) NOT NULL,
    `created_at` DATETIME NOT NULL,
    `last_seen_at` DATETIME NOT NULL,
    `expires_at` DATETIME NOT NULL,
    KEY `ix_user` (`user_id`),
    CONSTRAINT `fk_on_tok_user` FOREIGN KEY (`user_id`) REFERENCES `on_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `on_email_tokens` (
    `token_hash` CHAR(64) NOT NULL PRIMARY KEY,
    `user_id` INT UNSIGNED NOT NULL,
    `created_at` DATETIME NOT NULL,
    `expires_at` DATETIME NOT NULL,
    KEY `ix_user` (`user_id`),
    CONSTRAINT `fk_on_etok_user` FOREIGN KEY (`user_id`) REFERENCES `on_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `on_attempts` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `kind` VARCHAR(20) NOT NULL,
    `ip` VARCHAR(45) NOT NULL,
    `created_at` DATETIME NOT NULL,
    KEY `ix_kind_ip` (`kind`, `ip`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `on_groups` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `slug` VARCHAR(40) NOT NULL,
    `name` VARCHAR(80) NOT NULL,
    `description` VARCHAR(300) NOT NULL DEFAULT '',
    `owner_id` INT UNSIGNED NULL,
    `status` ENUM('active','disabled') NOT NULL DEFAULT 'active',
    `timezone` VARCHAR(64) NOT NULL DEFAULT 'Europe/Rome',
    `langs` VARCHAR(255) NOT NULL DEFAULT '["en"]',
    `page` TEXT NULL,
    `terms` TEXT NULL,
    `terms_rev` CHAR(12) NOT NULL DEFAULT '',
    `from_email` VARCHAR(190) NOT NULL DEFAULT '',
    `from_name` VARCHAR(80) NOT NULL DEFAULT '',
    `reply_to` VARCHAR(190) NOT NULL DEFAULT '',
    `smtp_sealed` TEXT NULL,
    `smtp_checked_at` DATETIME NULL,
    `rate_per_hour` SMALLINT UNSIGNED NOT NULL DEFAULT 200,
    `created_at` DATETIME NOT NULL,
    `updated_at` DATETIME NOT NULL,
    UNIQUE KEY `uq_slug` (`slug`),
    CONSTRAINT `fk_on_grp_owner` FOREIGN KEY (`owner_id`) REFERENCES `on_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `on_members` (
    `group_id` INT UNSIGNED NOT NULL,
    `user_id` INT UNSIGNED NOT NULL,
    `role` ENUM('user','moderator','publisher','admin','owner') NOT NULL DEFAULT 'user',
    `created_at` DATETIME NOT NULL,
    PRIMARY KEY (`group_id`, `user_id`),
    KEY `ix_user` (`user_id`),
    CONSTRAINT `fk_on_mem_group` FOREIGN KEY (`group_id`) REFERENCES `on_groups` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_on_mem_user` FOREIGN KEY (`user_id`) REFERENCES `on_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `on_invites` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `group_id` INT UNSIGNED NOT NULL,
    `email` VARCHAR(190) NOT NULL,
    `role` ENUM('user','moderator','publisher','admin') NOT NULL DEFAULT 'user',
    `invited_by` INT UNSIGNED NULL,
    `created_at` DATETIME NOT NULL,
    UNIQUE KEY `uq_group_email` (`group_id`, `email`),
    KEY `ix_email` (`email`),
    CONSTRAINT `fk_on_inv_group` FOREIGN KEY (`group_id`) REFERENCES `on_groups` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `on_subscribers` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `group_id` INT UNSIGNED NOT NULL,
    `email` VARCHAR(190) NOT NULL,
    `lang` VARCHAR(5) NOT NULL,
    `browser_lang` VARCHAR(5) NOT NULL DEFAULT '',
    `browser` VARCHAR(30) NOT NULL DEFAULT '',
    `source` ENUM('page','widget','import') NOT NULL DEFAULT 'page',
    `status` ENUM('pending','active','unsubscribed') NOT NULL DEFAULT 'pending',
    `token` CHAR(32) NOT NULL,
    `confirm_hash` CHAR(64) NULL,
    `confirm_sent_at` DATETIME NULL,
    `terms_rev` CHAR(12) NOT NULL DEFAULT '',
    `created_at` DATETIME NOT NULL,
    `confirmed_at` DATETIME NULL,
    `unsubscribed_at` DATETIME NULL,
    `unsub_reason` VARCHAR(500) NOT NULL DEFAULT '',
    UNIQUE KEY `uq_group_email` (`group_id`, `email`),
    UNIQUE KEY `uq_token` (`token`),
    KEY `ix_group_status` (`group_id`, `status`, `lang`),
    KEY `ix_confirm` (`confirm_hash`),
    CONSTRAINT `fk_on_sub_group` FOREIGN KEY (`group_id`) REFERENCES `on_groups` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `on_templates` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `group_id` INT UNSIGNED NOT NULL,
    `name` VARCHAR(80) NOT NULL,
    `doc` MEDIUMTEXT NOT NULL,
    `created_by` INT UNSIGNED NULL,
    `created_at` DATETIME NOT NULL,
    `updated_at` DATETIME NOT NULL,
    KEY `ix_group` (`group_id`),
    CONSTRAINT `fk_on_tpl_group` FOREIGN KEY (`group_id`) REFERENCES `on_groups` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `on_newsletters` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `group_id` INT UNSIGNED NOT NULL,
    `subject` VARCHAR(200) NOT NULL DEFAULT '',
    `preheader` VARCHAR(200) NOT NULL DEFAULT '',
    `lang` VARCHAR(5) NULL,
    `doc` MEDIUMTEXT NOT NULL,
    `status` ENUM('draft','pending','scheduled','rejected','expired','cancelled','sending','sent','failed') NOT NULL DEFAULT 'draft',
    `author_id` INT UNSIGNED NULL,
    `proposed_at` DATETIME NULL,
    `scheduled_at` DATETIME NULL,
    `submitted_at` DATETIME NULL,
    `reviewer_id` INT UNSIGNED NULL,
    `reviewed_at` DATETIME NULL,
    `review_note` VARCHAR(500) NOT NULL DEFAULT '',
    `reminded_at` DATETIME NULL,
    `started_at` DATETIME NULL,
    `sent_at` DATETIME NULL,
    `total` INT UNSIGNED NOT NULL DEFAULT 0,
    `sent_count` INT UNSIGNED NOT NULL DEFAULT 0,
    `failed_count` INT UNSIGNED NOT NULL DEFAULT 0,
    `rev` INT UNSIGNED NOT NULL DEFAULT 0,
    `created_at` DATETIME NOT NULL,
    `updated_at` DATETIME NOT NULL,
    KEY `ix_group_status` (`group_id`, `status`),
    KEY `ix_due` (`status`, `scheduled_at`),
    CONSTRAINT `fk_on_nl_group` FOREIGN KEY (`group_id`) REFERENCES `on_groups` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_on_nl_author` FOREIGN KEY (`author_id`) REFERENCES `on_users` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_on_nl_reviewer` FOREIGN KEY (`reviewer_id`) REFERENCES `on_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `on_deliveries` (
    `newsletter_id` INT UNSIGNED NOT NULL,
    `subscriber_id` INT UNSIGNED NOT NULL,
    `status` ENUM('queued','sent','failed') NOT NULL DEFAULT 'queued',
    `error` VARCHAR(200) NOT NULL DEFAULT '',
    `sent_at` DATETIME NULL,
    PRIMARY KEY (`newsletter_id`, `subscriber_id`),
    KEY `ix_queue` (`newsletter_id`, `status`),
    CONSTRAINT `fk_on_del_nl` FOREIGN KEY (`newsletter_id`) REFERENCES `on_newsletters` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_on_del_sub` FOREIGN KEY (`subscriber_id`) REFERENCES `on_subscribers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `on_images` (
    `id` CHAR(20) NOT NULL PRIMARY KEY,
    `group_id` INT UNSIGNED NOT NULL,
    `mime` VARCHAR(20) NOT NULL,
    `width` SMALLINT UNSIGNED NOT NULL,
    `height` SMALLINT UNSIGNED NOT NULL,
    `bytes` INT UNSIGNED NOT NULL,
    `data` MEDIUMBLOB NOT NULL,
    `created_by` INT UNSIGNED NULL,
    `created_at` DATETIME NOT NULL,
    KEY `ix_group` (`group_id`),
    CONSTRAINT `fk_on_img_group` FOREIGN KEY (`group_id`) REFERENCES `on_groups` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `on_meta` (k, v) VALUES ('schema_version', '3') ON DUPLICATE KEY UPDATE v = VALUES(v);
